INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG05_ADULT_012', 'Adult education', 'Advocacy and global citizenship', 'Promote inclusive communication that challenges stereotypes and uplifts marginalised voices.', 'Active'), ('CFV_SDG05_ADULT_013', 'Adult education', 'Advocacy and global citizenship', 'Stay informed and responsive to global gender equality trends, data and frameworks.', 'Active'), ('CFV_SDG05_ADULT_014', 'Adult education', 'Transformative change and accountability', 'Believe in education as a transformative tool to dismantle cycles of discrimination and empower all genders.', 'Active'), ('CFV_SDG05_ADULT_015', 'Adult education', 'Transformative change and accountability', 'Embrace lifelong learning and reflection to evolve strategies that advance gender equality.', 'Active'), ('CFV_SDG05_ADULT_016', 'Adult education', 'Transformative change and accountability', 'Cultivate a personal commitment to building just, inclusive and equitable academic and professional spaces.', 'Active'), ('CFV_SDG05_ADULT_017', 'Adult education', 'Transformative change and accountability', 'Value lifelong learning and financial independence in promoting gender equality.', 'Active'), ('CFV_SDG05_ADULT_018', 'Adult education', 'Community engagement, monitoring and gender mainstreaming', 'Commitment to promoting gender equality as a shared community responsibility.', 'Active'), ('CFV_SDG05_ADULT_019', 'Adult education', 'Community engagement, monitoring and gender mainstreaming', 'Appreciation of inclusive community spaces where women and marginalised groups can voice concerns, share experiences and support one another.', 'Active'), ('CFV_SDG05_ADULT_020', 'Adult education', 'Community engagement, monitoring and gender mainstreaming', 'Respect for transparency and accountability in monitoring gender progress and learning from both successes and challenges.', 'Active'), ('CFV_SDG05_ADULT_021', 'Adult education', 'Community engagement, monitoring and gender mainstreaming', 'Belief in continuous improvement through reflection, feedback and collective action toward gender justice.', 'Active'), ('CFV_SDG06_SEC_001', 'Secondary education', 'Personal responsibility in water use', 'Encourage a sense of individual responsibility by helping students understand their direct and indirect water use and how it affects local and global water resources.', 'Active'), ('CFV_SDG06_SEC_002', 'Secondary education', 'Personal responsibility in water use', 'Encourage conscious daily decisions to reduce personal water footprints – turning off taps, reusing water, choosing low-water-consumption products, and managing online activity responsibly (for example, limiting unnecessary screen time due to digital water costs).', 'Active'), ('CFV_SDG06_SEC_003', 'Secondary education', 'Appreciation of water as a shared, finite resource', 'Learn to appreciate water’s scarcity in many regions and the ethical importance of preserving water reserves, particularly under conditions of drought, food insecurity and urban expansion.', 'Active'), ('CFV_SDG06_SEC_004', 'Secondary education', 'Appreciation of water as a shared, finite resource', 'Encourage empathy with communities facing water challenges, reinforcing the idea that water access is a human right and a global justice issue.', 'Active'), ('CFV_SDG06_SEC_005', 'Secondary education', 'Understanding the water footprint', 'Develop a mindset that sees water not only as what flows from taps, but as embedded in the food we eat, clothes we wear and things we use – promoting conscious consumption.', 'Active'), ('CFV_SDG06_SEC_006', 'Secondary education', 'Understanding the water footprint', 'Motivate students to reduce footprints: act – changing diets, reducing waste and advocating for sustainable production – to shrink their own water footprint.', 'Active'), ('CFV_SDG06_SEC_007', 'Secondary education', 'Protection of water quality for all life', 'Emphasise the link between human behaviour and the wellbeing of aquatic life and ecosystems, nurturing a respect for water’s role in sustaining biodiversity.', 'Active'), ('CFV_SDG06_SEC_008', 'Secondary education', 'Protection of water quality for all life', 'Encourage active engagement in protecting water sources from pollution and degradation, encouraging participation in conservation activities like clean-ups or awareness campaigns.', 'Active'), ('CFV_SDG06_SEC_009', 'Secondary education', 'Recognition of competing demands and need for equity', 'Explore ethical decision-making: thoughtful consideration of how to balance competing demands for water – agriculture, industry, urban populations, wildlife – while prioritising equity and sustainability.', 'Active'), ('CFV_SDG06_SEC_010', 'Secondary education', 'Recognition of competing demands and need for equity', 'Recognise that vulnerable communities often bear the greatest burden from poor water management or scarcity.', 'Active'), ('CFV_SDG06_SEC_011', 'Secondary education', 'Water as interconnected with environment and society', 'Appreciate that water systems are deeply connected to energy, food, ecosystems and human health – reinforcing a holistic, interdisciplinary perspective.', 'Active'), ('CFV_SDG06_SEC_012', 'Secondary education', 'Water as interconnected with environment and society', 'Understand informed decision-making: examine water challenges through environmental, technological, social and economic lenses, developing mature attitudes toward sustainable solutions.', 'Active'), ('CFV_SDG06_SEC_013', 'Secondary education', 'Value for interdisciplinary and collective approaches', 'Appreciate working across disciplines (for example, science, social studies, technology, arts) to co-create practical and inclusive water solutions.', 'Active'), ('CFV_SDG06_SEC_014', 'Secondary education', 'Ethical computing and hidden water use', 'Develop awareness of digital water costs: cultivate mindfulness that even virtual activities – like streaming, gaming or long screen use – consume water through energy use.', 'Active'), ('CFV_SDG06_SEC_015', 'Secondary education', 'Ethical computing and hidden water use', 'Encourage responsible digital use: powering down unused devices or tabs, as part of a broader ethos of sustainability.', 'Active'), ('CFV_SDG06_SEC_016', 'Secondary education', 'Global citizenship and collective action', 'Appreciate that responsible water use, and advocacy are part of global citizenship, where everyone’s actions contribute to systemic change.', 'Active'), ('CFV_SDG06_SEC_017', 'Secondary education', 'Global citizenship and collective action', 'Engage in a values-based belief that youth can influence water conservation, policy development and climate resilience in their communities and beyond.', 'Active'), ('CFV_SDG06_SEC_018', 'Secondary education', 'Link social, technological and scientific aspects', 'Connect ethical dilemmas to broader societal, technological and scientific issues surrounding water use.', 'Active'), ('CFV_SDG06_SEC_019', 'Secondary education', 'Link social, technological and scientific aspects', 'Engage in debates on water allocation policies, balancing human needs with environmental protection.', 'Active'), ('CFV_SDG06_SEC_020', 'Secondary education', 'Link social, technological and scientific aspects', 'Discuss issues like water rights, conservation efforts and industrial water use.', 'Active'), ('CFV_SDG06_TVET_001', 'TVET', 'Responsibility and ethics', 'Take personal and professional responsibility for water conservation and infrastructure integrity.', 'Active'), ('CFV_SDG06_TVET_002', 'TVET', 'Responsibility and ethics', 'Develop a commitment to environmental protection and responsible waste disposal.', 'Active'), ('CFV_SDG06_TVET_003', 'TVET', 'Responsibility and ethics', 'Cultivate a sense of urgency and care in ensuring safe drinking water and sanitation for all.', 'Active'), ('CFV_SDG06_TVET_004', 'TVET', 'Sustainability and stewardship', 'Value water as a limited, shared and vital resource.', 'Active'), ('CFV_SDG06_TVET_005', 'TVET', 'Sustainability and stewardship', 'Embrace a sustainability mindset in all technical and operational decisions.', 'Active'), ('CFV_SDG06_TVET_006', 'TVET', 'Sustainability and stewardship', 'Promote the use of renewable energy and efficient systems in the water and sanitation sectors.', 'Active'), ('CFV_SDG06_TVET_007', 'TVET', 'Professional contribution and leadership', 'Be motivated to make meaningful contributions to a more sustainable society through one’s trade.', 'Active'), ('CFV_SDG06_TVET_008', 'TVET', 'Professional contribution and leadership', 'Demonstrate leadership in keeping hygiene and sustainability practices in workplaces.', 'Active'), ('CFV_SDG06_TVET_009', 'TVET', 'Professional contribution and leadership', 'Advocate for environmentally sound business practices within the water and sanitation industry.', 'Active'), ('CFV_SDG06_TVET_010', 'TVET', 'Innovation and lifelong learning', 'Stay informed about emerging technologies and practices in water management.', 'Active'), ('CFV_SDG06_TVET_011', 'TVET', 'Innovation and lifelong learning', 'Appreciate the interdisciplinary nature of water challenges and solutions.', 'Active'), ('CFV_SDG06_TVET_012', 'TVET', 'Innovation and lifelong learning', 'Engage with continuous professional development and technological updates.', 'Active'), ('CFV_SDG06_TVET_013', 'TVET', 'Equity and social good', 'Recognise the role of skilled workers in ensuring water justice and reducing water inequality.', 'Active'), ('CFV_SDG06_TVET_014', 'TVET', 'Equity and social good', 'Support inclusive access to clean water and sanitation in all settings – rural, urban, public and private.', 'Active'), ('CFV_SDG06_TVET_015', 'TVET', 'Equity and social good', 'Encourage community participation and empowerment in water management initiatives.', 'Active'), ('CFV_SDG06_TVET_016', 'TVET', 'Crisis response and problem solving', 'Respond effectively to emergencies such as pipe bursts, contamination or system failure.', 'Active'), ('CFV_SDG06_TVET_017', 'TVET', 'Crisis response and problem solving', 'Propose context-specific solutions to water access and sanitation challenges.', 'Active'), ('CFV_SDG06_TER_001', 'Tertiary education', 'Ethical and environmental responsibility', 'Value water and sanitation as fundamental human rights, with a strong ethical stance against exclusion and inequity in access.', 'Active'), ('CFV_SDG06_TER_002', 'Tertiary education', 'Ethical and environmental responsibility', 'Commit to reducing ecological footprints by promoting environmentally responsible behaviours in water use, energy management, waste reduction and emissions control.', 'Active'), ('CFV_SDG06_TER_003', 'Tertiary education', 'Ethical and environmental responsibility', 'Respect freshwater ecosystems as essential for biodiversity, climate resilience and intergenerational sustainability.', 'Active') ON CONFLICT DO NOTHING;